#!/usr/bin/env python3
"""
Find the exact columns for Total Supply, Import, Total Use, GFCF, Final Consumption, Export
"""
from openpyxl import load_workbook

wb = load_workbook('/root/test - demand.xlsx')
supply_sheet = wb['SUPPLY (38-38)-2024']
use_sheet = wb['USE (38-38)-2024']

print("="*80)
print("SUPPLY SHEET - Scanning all columns in rows 1-3:")
print("="*80)

# Scan all columns in the header area
for row_idx in [1, 2, 3]:
    print(f"\nRow {row_idx}:")
    for col_idx in range(1, 100):
        val = supply_sheet.cell(row_idx, col_idx).value
        if val and str(val).strip():
            col_letter = supply_sheet.cell(row_idx, col_idx).column_letter
            print(f"  {col_letter}{row_idx}: {val}")
        if col_idx > 60 and not val:
            # If we hit 5 empty columns, assume we're past the data
            empty_count = 0
            for check_col in range(col_idx, col_idx + 5):
                if not supply_sheet.cell(row_idx, check_col).value:
                    empty_count += 1
            if empty_count >= 5:
                break

print("\n" + "="*80)
print("USE SHEET - Scanning all columns in rows 1-3:")
print("="*80)

for row_idx in [1, 2, 3]:
    print(f"\nRow {row_idx}:")
    for col_idx in range(1, 100):
        val = use_sheet.cell(row_idx, col_idx).value
        if val and str(val).strip():
            col_letter = use_sheet.cell(row_idx, col_idx).column_letter
            print(f"  {col_letter}{row_idx}: {val}")
        if col_idx > 60 and not val:
            empty_count = 0
            for check_col in range(col_idx, col_idx + 5):
                if not use_sheet.cell(row_idx, check_col).value:
                    empty_count += 1
            if empty_count >= 5:
                break

# Check for total columns at the end of data rows
print("\n" + "="*80)
print("Checking row 4 (first data row) for all columns:")
print("="*80)

print("\nSUPPLY Sheet Row 4:")
for col_idx in range(1, 60):
    val = supply_sheet.cell(4, col_idx).value
    if val is not None:
        col_letter = supply_sheet.cell(4, col_idx).column_letter
        print(f"  {col_letter}: {val}")

print("\nUSE Sheet Row 4:")
for col_idx in range(1, 60):
    val = use_sheet.cell(4, col_idx).value
    if val is not None:
        col_letter = use_sheet.cell(4, col_idx).column_letter
        print(f"  {col_letter}: {val}")

# Look at the last row to find totals
print("\n" + "="*80)
print("Finding the last data row with 'Total'...")
print("="*80)

for row_idx in range(40, 50):
    val_a = supply_sheet.cell(row_idx, 1).value
    val_b = supply_sheet.cell(row_idx, 2).value
    if val_a or val_b:
        print(f"SUPPLY Row {row_idx}: A={val_a}, B={val_b}")

print()
for row_idx in range(40, 50):
    val_a = use_sheet.cell(row_idx, 1).value
    val_b = use_sheet.cell(row_idx, 2).value
    if val_a or val_b:
        print(f"USE Row {row_idx}: A={val_a}, B={val_b}")

